E = \frac{h_{\text{OA entering}} - h_{\text{OA leaving}}}{h_{\text{OA entering}} - h_{\text{RA}}} \geq 50\%

h_{\text{OA entering}} = \text{enthalpy of the outdoor air entering the energy recovery system, kJ/kg dry air (Btu/lb. dry air)}

h_{\text{OA leaving}} = \text{enthalpy of the outdoor air leaving the energy recovery system, kJ/kg dry air (Btu/lb. dry air)}

h_{\text{RA}} = \text{enthalpy of the return air entering the energy recovery system, kJ/kg dry air (Btu/lb. dry air)}
